//! Type, effect, trait, and ownership checking.
//!
//! [`TypeChecker`] consumes a resolved module. It checks declarations and runtime
//! expressions, infers concrete types and effect rows, records coercions and
//! contextual defaults, and selects trait evidence. Ownership analysis records
//! moves, borrows, mutations, captures, and initialization checks.
//!
//! A successful [`TypedModule`] carries the checked facts needed by lowering.
//! Generic obligations remain explicit recipes for concrete substitution;
//! checking rejects invalid source programs with source-located diagnostics.
//! Lowering owns specialization and cleanup planning. Codegen never receives
//! this checker interface.

use std::cell::{Cell, RefCell};
use std::collections::{HashMap, HashSet};
use std::fmt;

use crate::{
    BuiltinType, DefinitionId, FloatType, FunctionId, IntegerType, ModuleId, ResolvedFunction,
    ResolvedModule, SymbolId, TraitId, TraitMethodId, TypeId, TypeParameterId,
};
use staple_syntax::{
    Accessor, Binding, Diagnostic, Expression, Item, Module, Pattern, PatternBindingKind,
    ProductExpression, ProductType, Span, Syntax, SyntaxId, Type, TypeDeclaration,
    TypeDeclarationKind, TypeParameterPattern,
};

mod product_spreads;

enum PlaceIssue {
    /// The root binding is not declared `mut` and cannot be reassigned.
    NotReassignable(String),
    /// The root binding is not declared `mut` and cannot be written through.
    NotMutable(String),
    /// The target is not a place at all (e.g. a temporary).
    NotAPlace,
}

fn place_expression_name(expression: &Expression) -> String {
    match expression {
        Expression::Name(name) => name.name.clone(),
        Expression::Access(access) => match &access.accessor {
            Accessor::Name(name) => name.clone(),
            Accessor::Index(index) => index.clone(),
            Accessor::Method(name) => name.clone(),
            Accessor::Representation => "*".to_string(),
        },
        _ => "value".to_string(),
    }
}

/// The companion-owning type a source type names; aliases are transparent.
fn source_type_id(module: &ResolvedModule, ty: &Type) -> Option<TypeId> {
    match ty {
        Type::Named(named) => module
            .type_for(named.syntax.id)
            .and_then(|id| module.companion_owner(id)),
        Type::Application(application) => source_type_id(module, &application.callee),
        _ => None,
    }
}

fn checked_type_id(ty: &CheckedType) -> Option<TypeId> {
    match ty {
        CheckedType::TypeConstructor { id, .. }
        | CheckedType::Opaque { id, .. }
        | CheckedType::Wrapper { id, .. } => Some(*id),
        _ => None,
    }
}

fn checked_type_arguments(ty: &CheckedType) -> &[CheckedType] {
    match ty {
        CheckedType::TypeConstructor { arguments, .. }
        | CheckedType::Opaque { arguments, .. }
        | CheckedType::Wrapper { arguments, .. } => arguments,
        _ => &[],
    }
}

/// Binds a dependency template's declared parameters to a resource
/// application's arguments. Unlike [`TypeChecker::bind_type_argument`], this
/// never reports diagnostics: dependency eligibility was already checked when
/// the declaration was collected, and closing runs while computing effects.
fn bind_resource_type_argument(
    module: &ResolvedModule,
    pattern: &TypeParameterPattern,
    argument: &CheckedType,
    substitutions: &mut HashMap<TypeParameterId, CheckedType>,
) {
    match pattern {
        TypeParameterPattern::Binding(binding) => {
            if let Some(id) = module.type_parameter_for(binding.syntax.id) {
                substitutions.insert(id, argument.clone());
            }
        }
        TypeParameterPattern::Effect(binding) => {
            if let Some(id) = module.type_parameter_for(binding.syntax.id) {
                substitutions.insert(id, argument.clone());
            }
        }
        TypeParameterPattern::Product(product) => {
            if product.elements.len() == 1 {
                bind_resource_type_argument(module, &product.elements[0], argument, substitutions);
            } else if let CheckedType::Product(argument) = argument {
                for (pattern, element) in product.elements.iter().zip(argument.iter_positions()) {
                    bind_resource_type_argument(
                        module,
                        pattern,
                        &element.value_type,
                        substitutions,
                    );
                }
            }
        }
        TypeParameterPattern::Splice(_) => {}
    }
}

/// The compiler-provided type a checked scalar corresponds to, if any. This
/// lets a pipe stage find a companion on a builtin numeric type the same way
/// it finds one on a user-declared type.
fn checked_builtin_type(ty: &CheckedType) -> Option<BuiltinType> {
    Some(match ty {
        CheckedType::I8 => BuiltinType::Integer(IntegerType::I8),
        CheckedType::I16 => BuiltinType::Integer(IntegerType::I16),
        CheckedType::I32 => BuiltinType::Integer(IntegerType::I32),
        CheckedType::I64 => BuiltinType::Integer(IntegerType::I64),
        CheckedType::U8 => BuiltinType::Integer(IntegerType::U8),
        CheckedType::U16 => BuiltinType::Integer(IntegerType::U16),
        CheckedType::U32 => BuiltinType::Integer(IntegerType::U32),
        CheckedType::U64 => BuiltinType::Integer(IntegerType::U64),
        CheckedType::ISize => BuiltinType::Integer(IntegerType::ISize),
        CheckedType::USize => BuiltinType::Integer(IntegerType::USize),
        CheckedType::F32 => BuiltinType::Float(FloatType::F32),
        CheckedType::F64 => BuiltinType::Float(FloatType::F64),
        CheckedType::String => BuiltinType::String,
        CheckedType::CChar => BuiltinType::CChar,
        ty if ty.is_cstring() => BuiltinType::CString,

        _ => return None,
    })
}

/// Where a declaration-site span points, for diagnostics reported elsewhere.
fn span_location(span: &Span) -> String {
    match span {
        Span::User {
            location: Some(location),
            ..
        } => format!("line {}, column {}", location.line, location.column),
        Span::User { range, .. } => format!("byte {}", range.start),
        Span::Compiler => "its declaration".to_owned(),
    }
}

fn valid_resource_type(value_type: &CheckedType) -> bool {
    matches!(
        value_type,
        CheckedType::Wrapper { .. }
            | CheckedType::Opaque { .. }
            | CheckedType::RawPtr { .. }
            | CheckedType::RawMutPtr { .. }
            | CheckedType::RawOpaquePtr
            | CheckedType::RawOpaqueMutPtr
            | CheckedType::Never
    ) || checked_builtin_type(value_type).is_some()
}

fn checked_builtin_type_id(module: &ResolvedModule, ty: &CheckedType) -> Option<TypeId> {
    module.type_for_builtin(checked_builtin_type(ty)?)
}

#[derive(Debug, Clone)]
pub struct CheckedTraitBound {
    pub trait_id: TraitId,
    pub arguments: Vec<CheckedType>,
}

impl PartialEq for CheckedTraitBound {
    fn eq(&self, other: &Self) -> bool {
        self.trait_id == other.trait_id && types_equivalent_list(&self.arguments, &other.arguments)
    }
}
impl Eq for CheckedTraitBound {}

#[derive(Debug, Clone)]
pub struct CheckedSubtypeBound {
    pub parameter: TypeParameterId,
    pub supertype: CheckedType,
}

impl PartialEq for CheckedSubtypeBound {
    fn eq(&self, other: &Self) -> bool {
        self.parameter == other.parameter && types_equivalent(&self.supertype, &other.supertype)
    }
}
impl Eq for CheckedSubtypeBound {}

#[derive(Debug, Clone)]
pub struct CheckedDefaultBound {
    pub parameter: TypeParameterId,
    pub default: CheckedType,
}

impl PartialEq for CheckedDefaultBound {
    fn eq(&self, other: &Self) -> bool {
        self.parameter == other.parameter && types_equivalent(&self.default, &other.default)
    }
}
impl Eq for CheckedDefaultBound {}

